import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
// Cooperative tiled direct 2D convolution.
// Each CTA computes an 8x8 spatial output tile for 4 output channels.
// The CTA cooperatively stages the strided input halo tile in shared memory,
// including zero padding for out-of-range input locations.
constexpr int TILE_H = 8;
constexpr int TILE_W = 8;
constexpr int COUT_TILE = 4;
constexpr int BLOCK_THREADS = TILE_H * TILE_W * COUT_TILE;
// Specialized register-blocked kernel for C_in=3, K=11, stride=4, pad=2.
// Each CTA computes an 8x8 spatial tile for 16 output channels.
// Each thread computes a 2x2 spatial block for 2 output channels (8 outputs),
// reusing staged input values across channels and staged weights across the
// 2x2 spatial block to raise the FMA-to-load ratio (register blocking).
constexpr int S_C_IN = 3;
constexpr int S_K = 11;
constexpr int S_STRIDE = 4;
constexpr int S_PAD = 2;
constexpr int S_COUT_TILE = 16;
constexpr int S_IN_H = (TILE_H - 1) * S_STRIDE + S_K; // 39
constexpr int S_IN_W = (TILE_W - 1) * S_STRIDE + S_K; // 39
constexpr int S_ROW = S_IN_W + 1;                     // 40, float4-friendly stride
constexpr int S_PLANE = S_IN_H * S_ROW;               // 1560
constexpr int S_IN_ELEMS = S_C_IN * S_PLANE;          // 4680
constexpr int S_W_ELEMS = S_COUT_TILE * S_C_IN * S_K * S_K; // 5808
constexpr int S_W_SLAB = 2 * S_COUT_TILE * S_K;   // 352: one (c,kh) weight slab for all 32 output channels
constexpr int S_THREADS = 4 * 8 * 4;                  // 128
__global__ void __launch_bounds__(S_THREADS) conv2d_forward_kernel_s(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int H_in, const int W_in,
    const int C_out, const int H_out, const int W_out)
{
    extern __shared__ float sh_mem[];
    float* sh_input = sh_mem;
    float* sh_weight = sh_mem + S_IN_ELEMS;
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    const int tile_w = blockIdx.x % tiles_w;
    const int tile_h = blockIdx.x / tiles_w;
    const int h_out0 = tile_h * TILE_H;
    const int w_out0 = tile_w * TILE_W;
    const int c_out0 = blockIdx.y * S_COUT_TILE;
    const int n = blockIdx.z;
    const int in_h0 = h_out0 * S_STRIDE - S_PAD;
    const int in_w0 = w_out0 * S_STRIDE - S_PAD;
    const int tid = threadIdx.x + 4 * threadIdx.y + 32 * threadIdx.z;
    // Stage the strided input halo tile: one padded shared-memory row per
    // thread, using 16B vectorized global loads for the row interior.
    const bool vec_ok = (W_in & 3) == 0; // in_w0 % 4 == 2 for every tile
    for (int row = tid; row < S_C_IN * S_IN_H; row += S_THREADS) {
        const int c = row / S_IN_H;
        const int y = row - c * S_IN_H;
        const int h_in = in_h0 + y;
        float* sh_row = sh_input + c * S_PLANE + y * S_ROW;
        if (h_in < 0 || h_in >= H_in) {
            #pragma unroll
            for (int x = 0; x < S_ROW; ++x) sh_row[x] = 0.0f;
            continue;
        }
        const float* g_row = input + (((long long)n * S_C_IN + c) * H_in + h_in) * W_in + in_w0;
        sh_row[S_IN_W] = 0.0f; // permanent zero pad column
        const int x0 = max(0, -in_w0);            // first in-range x
        const int x1 = min(S_IN_W, W_in - in_w0); // one past last in-range x
        for (int x = 0; x < x0; ++x) sh_row[x] = 0.0f;
        for (int x = x1; x < S_IN_W; ++x) sh_row[x] = 0.0f;
        if (vec_ok && x1 > x0) {
            // in_w0 + x is 16B-aligned when x % 4 == 2 (W_in % 4 == 0)
            const int xs = min(x0 + ((2 - (x0 & 3)) & 3), x1);
            for (int x = x0; x < xs; ++x) sh_row[x] = g_row[x];
            const float4* g4 = reinterpret_cast<const float4*>(g_row + xs);
            const int n4 = (x1 - xs) >> 2;
            for (int i = 0; i < n4; ++i) {
                const float4 v = g4[i];
                const int xb = xs + 4 * i;
                sh_row[xb] = v.x; sh_row[xb + 1] = v.y;
                sh_row[xb + 2] = v.z; sh_row[xb + 3] = v.w;
            }
            for (int x = xs + (n4 << 2); x < x1; ++x) sh_row[x] = g_row[x];
        } else {
            for (int x = x0; x < x1; ++x) sh_row[x] = g_row[x];
        }
    }
    // Stage this CTA's weight slice with 16B vector loads (S_W_ELEMS is divisible by 4).
    const float* w_base = weight + (long long)c_out0 * (S_C_IN * S_K * S_K);
    const float4* w_base4 = reinterpret_cast<const float4*>(w_base);
    float4* sh_weight4 = reinterpret_cast<float4*>(sh_weight);
    for (int i = tid; i < S_W_ELEMS / 4; i += S_THREADS) {
        sh_weight4[i] = w_base4[i];
    }
    __syncthreads();
    const int tx = threadIdx.x; // 0..3 -> output cols tx*2, tx*2+1
    const int cg = threadIdx.y; // 0..7 -> output channels cg*2, cg*2+1
    const int ty = threadIdx.z; // 0..3 -> output rows ty*2, ty*2+1
    float s00a = 0.0f, s01a = 0.0f, s10a = 0.0f, s11a = 0.0f;
    float s00b = 0.0f, s01b = 0.0f, s10b = 0.0f, s11b = 0.0f;
    const int rbase = ty * 2 * S_STRIDE; // input row of first output row
    const int cbase = tx * 2 * S_STRIDE; // input col of first output col
    const float* wp = sh_weight + cg * 2 * (S_C_IN * S_K * S_K);
    #pragma unroll
    for (int c = 0; c < S_C_IN; ++c) {
        const float* plane = sh_input + c * S_PLANE;
        const float* w0 = wp + c * (S_K * S_K);
        const float* w1 = w0 + (S_C_IN * S_K * S_K);
        #pragma unroll
        for (int kh = 0; kh < S_K; ++kh) {
            const float4* row0 = reinterpret_cast<const float4*>(plane + (rbase + kh) * S_ROW + cbase);
            const float4* row1 = reinterpret_cast<const float4*>(plane + (rbase + kh + S_STRIDE) * S_ROW + cbase);
            const float a[16] = {row0[0].x, row0[0].y, row0[0].z, row0[0].w,
                                 row0[1].x, row0[1].y, row0[1].z, row0[1].w,
                                 row0[2].x, row0[2].y, row0[2].z, row0[2].w,
                                 row0[3].x, row0[3].y, row0[3].z, row0[3].w};
            const float b[16] = {row1[0].x, row1[0].y, row1[0].z, row1[0].w,
                                 row1[1].x, row1[1].y, row1[1].z, row1[1].w,
                                 row1[2].x, row1[2].y, row1[2].z, row1[2].w,
                                 row1[3].x, row1[3].y, row1[3].z, row1[3].w};
            const float* wr0 = w0 + kh * S_K;
            const float* wr1 = w1 + kh * S_K;
            #pragma unroll
            for (int kw = 0; kw < S_K; ++kw) {
                const float i00 = a[kw];
                const float i01 = a[kw + S_STRIDE];
                const float i10 = b[kw];
                const float i11 = b[kw + S_STRIDE];
                const float wv0 = wr0[kw];
                const float wv1 = wr1[kw];
                s00a += i00 * wv0; s01a += i01 * wv0; s10a += i10 * wv0; s11a += i11 * wv0;
                s00b += i00 * wv1; s01b += i01 * wv1; s10b += i10 * wv1; s11b += i11 * wv1;
            }
        }
    }
    const int h0 = h_out0 + ty * 2;
    const int w0o = w_out0 + tx * 2;
    const int cA = c_out0 + cg * 2;
    const int cB = cA + 1;
    const float bA = bias[cA];
    const float bB = bias[cB];
    float* out_base = output + ((long long)n * C_out) * H_out * W_out;
    if (h0 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0) * W_out;
        float* rowB = out_base + ((long long)cB * H_out + h0) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s00a + bA; rowB[w0o] = s00b + bB; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s01a + bA; rowB[w0o + 1] = s01b + bB; }
    }
    if (h0 + 1 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0 + 1) * W_out;
        float* rowB = out_base + ((long long)cB * H_out + h0 + 1) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s10a + bA; rowB[w0o] = s10b + bB; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s11a + bA; rowB[w0o + 1] = s11b + bB; }
    }
}
// Fused-channel variant: each CTA computes 32 output channels over one
// staged input halo tile, and each thread register-blocks FOUR output
// channels for its 2x2 spatial block (16 accumulators). The 2x2 spatial
// input values (a[16]/b[16]) are read from shared memory once per (c, kh)
// and reused across all four channels from registers, instead of being
// re-read for every 16-channel group. This roughly halves shared-memory
// traffic per FMA, which is the limiting resource of the compute loop.
__global__ void __launch_bounds__(S_THREADS) conv2d_forward_kernel_s2(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int H_in, const int W_in,
    const int C_out, const int H_out, const int W_out)
{
    extern __shared__ float sh_mem[];
    float* sh_input = sh_mem;
    float* sh_weight = sh_mem + S_IN_ELEMS;
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    const int tile_w = blockIdx.x % tiles_w;
    const int tile_h = blockIdx.x / tiles_w;
    const int h_out0 = tile_h * TILE_H;
    const int w_out0 = tile_w * TILE_W;
    const int c_out0 = blockIdx.y * (2 * S_COUT_TILE);
    const int n = blockIdx.z;
    const int in_h0 = h_out0 * S_STRIDE - S_PAD;
    const int in_w0 = w_out0 * S_STRIDE - S_PAD;
    const int tid = threadIdx.x + 4 * threadIdx.y + 32 * threadIdx.z;
    const float* w_base = weight + (long long)c_out0 * (S_C_IN * S_K * S_K);
    // Pipelined weight staging: instead of staging the whole 32-channel
    // weight slice in shared memory (~46KB), stream it as a double-buffered
    // sequence of (c, kh) slabs (352 floats each) with cp.async. This cuts
    // dynamic shared memory from ~65KB to ~21.5KB, lifting the shared-memory
    // occupancy limit (8.3% theoretical -> register-limited ~33%).
    auto stage_slab = [&](int kk, int buf) {
        const int c = kk / S_K;
        const int kh = kk - c * S_K;
        const float* src_base = w_base + (c * S_K + kh) * S_K;
        float* dst = sh_weight + buf * S_W_SLAB;
        for (int i = tid; i < S_W_SLAB; i += S_THREADS) {
            const int ch = i / S_K;
            const int kw = i - ch * S_K;
            const float* src = src_base + ch * (S_C_IN * S_K * S_K) + kw;
#if __CUDA_ARCH__ >= 800
            __pipeline_memcpy_async(dst + i, src, 4);
#else
            dst[i] = *src;
#endif
        }
#if __CUDA_ARCH__ >= 800
        __pipeline_commit();
#endif
    };
    // Prefetch the first weight slab so the DMA overlaps input staging below.
    stage_slab(0, 0);
    // Stage the strided input halo tile: one padded shared-memory row per
    // thread, using 16B vectorized global loads for the row interior.
    const bool vec_ok = (W_in & 3) == 0; // in_w0 % 4 == 2 for every tile
    for (int row = tid; row < S_C_IN * S_IN_H; row += S_THREADS) {
        const int c = row / S_IN_H;
        const int y = row - c * S_IN_H;
        const int h_in = in_h0 + y;
        float* sh_row = sh_input + c * S_PLANE + y * S_ROW;
        if (h_in < 0 || h_in >= H_in) {
            #pragma unroll
            for (int x = 0; x < S_ROW; ++x) sh_row[x] = 0.0f;
            continue;
        }
        const float* g_row = input + (((long long)n * S_C_IN + c) * H_in + h_in) * W_in + in_w0;
        sh_row[S_IN_W] = 0.0f; // permanent zero pad column
        const int x0 = max(0, -in_w0);            // first in-range x
        const int x1 = min(S_IN_W, W_in - in_w0); // one past last in-range x
        for (int x = 0; x < x0; ++x) sh_row[x] = 0.0f;
        for (int x = x1; x < S_IN_W; ++x) sh_row[x] = 0.0f;
        if (vec_ok && x1 > x0) {
            // in_w0 + x is 16B-aligned when x % 4 == 2 (W_in % 4 == 0)
            const int xs = min(x0 + ((2 - (x0 & 3)) & 3), x1);
            for (int x = x0; x < xs; ++x) sh_row[x] = g_row[x];
            const float4* g4 = reinterpret_cast<const float4*>(g_row + xs);
            const int n4 = (x1 - xs) >> 2;
            for (int i = 0; i < n4; ++i) {
                const float4 v = g4[i];
                const int xb = xs + 4 * i;
                sh_row[xb] = v.x; sh_row[xb + 1] = v.y;
                sh_row[xb + 2] = v.z; sh_row[xb + 3] = v.w;
            }
            for (int x = xs + (n4 << 2); x < x1; ++x) sh_row[x] = g_row[x];
        } else {
            for (int x = x0; x < x1; ++x) sh_row[x] = g_row[x];
        }
    }
    __syncthreads();
    const int tx = threadIdx.x; // 0..3 -> output cols tx*2, tx*2+1
    const int cg = threadIdx.y; // 0..7 -> output channels cg*4 .. cg*4+3
    const int ty = threadIdx.z; // 0..3 -> output rows ty*2, ty*2+1
    float s00a = 0.0f, s01a = 0.0f, s10a = 0.0f, s11a = 0.0f;
    float s00b = 0.0f, s01b = 0.0f, s10b = 0.0f, s11b = 0.0f;
    float s00c = 0.0f, s01c = 0.0f, s10c = 0.0f, s11c = 0.0f;
    float s00d = 0.0f, s01d = 0.0f, s10d = 0.0f, s11d = 0.0f;
    const int rbase = ty * 2 * S_STRIDE; // input row of first output row
    const int cbase = tx * 2 * S_STRIDE; // input col of first output col
    const int woff = cg * 4 * S_K; // this thread's 4 channel rows within a slab
    #pragma unroll
    for (int kk = 0; kk < S_C_IN * S_K; ++kk) {
        const int c = kk / S_K;
        const int kh = kk - c * S_K;
        if (kk + 1 < S_C_IN * S_K) {
            stage_slab(kk + 1, (kk + 1) & 1); // prefetch next slab into other buffer
        }
#if __CUDA_ARCH__ >= 800
        __pipeline_wait_prior(kk + 1 < S_C_IN * S_K ? 1 : 0);
#endif
        __syncthreads(); // make the staged slab visible to all threads
        const float* slab = sh_weight + (kk & 1) * S_W_SLAB;
        const float* plane = sh_input + c * S_PLANE;
        const float4* row0 = reinterpret_cast<const float4*>(plane + (rbase + kh) * S_ROW + cbase);
        const float4* row1 = reinterpret_cast<const float4*>(plane + (rbase + kh + S_STRIDE) * S_ROW + cbase);
        const float a[16] = {row0[0].x, row0[0].y, row0[0].z, row0[0].w,
                             row0[1].x, row0[1].y, row0[1].z, row0[1].w,
                             row0[2].x, row0[2].y, row0[2].z, row0[2].w,
                             row0[3].x, row0[3].y, row0[3].z, row0[3].w};
        const float b[16] = {row1[0].x, row1[0].y, row1[0].z, row1[0].w,
                             row1[1].x, row1[1].y, row1[1].z, row1[1].w,
                             row1[2].x, row1[2].y, row1[2].z, row1[2].w,
                             row1[3].x, row1[3].y, row1[3].z, row1[3].w};
        const float* wr0 = slab + woff;
        const float* wr1 = wr0 + S_K;
        const float* wr2 = wr1 + S_K;
        const float* wr3 = wr2 + S_K;
        #pragma unroll
        for (int kw = 0; kw < S_K; ++kw) {
            const float i00 = a[kw];
            const float i01 = a[kw + S_STRIDE];
            const float i10 = b[kw];
            const float i11 = b[kw + S_STRIDE];
            const float wv0 = wr0[kw];
            const float wv1 = wr1[kw];
            const float wv2 = wr2[kw];
            const float wv3 = wr3[kw];
            s00a += i00 * wv0; s01a += i01 * wv0; s10a += i10 * wv0; s11a += i11 * wv0;
            s00b += i00 * wv1; s01b += i01 * wv1; s10b += i10 * wv1; s11b += i11 * wv1;
            s00c += i00 * wv2; s01c += i01 * wv2; s10c += i10 * wv2; s11c += i11 * wv2;
            s00d += i00 * wv3; s01d += i01 * wv3; s10d += i10 * wv3; s11d += i11 * wv3;
        }
        __syncthreads(); // all threads done before this buffer is restaged
    }
    const int h0 = h_out0 + ty * 2;
    const int w0o = w_out0 + tx * 2;
    const int cA = c_out0 + cg * 4;
    const float4 b4 = *reinterpret_cast<const float4*>(bias + cA);
    float* out_base = output + ((long long)n * C_out) * H_out * W_out;
    if (h0 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0) * W_out;
        float* rowB = out_base + ((long long)(cA + 1) * H_out + h0) * W_out;
        float* rowC = out_base + ((long long)(cA + 2) * H_out + h0) * W_out;
        float* rowD = out_base + ((long long)(cA + 3) * H_out + h0) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s00a + b4.x; rowB[w0o] = s00b + b4.y; rowC[w0o] = s00c + b4.z; rowD[w0o] = s00d + b4.w; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s01a + b4.x; rowB[w0o + 1] = s01b + b4.y; rowC[w0o + 1] = s01c + b4.z; rowD[w0o + 1] = s01d + b4.w; }
    }
    if (h0 + 1 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0 + 1) * W_out;
        float* rowB = out_base + ((long long)(cA + 1) * H_out + h0 + 1) * W_out;
        float* rowC = out_base + ((long long)(cA + 2) * H_out + h0 + 1) * W_out;
        float* rowD = out_base + ((long long)(cA + 3) * H_out + h0 + 1) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s10a + b4.x; rowB[w0o] = s10b + b4.y; rowC[w0o] = s10c + b4.z; rowD[w0o] = s10d + b4.w; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s11a + b4.x; rowB[w0o + 1] = s11b + b4.y; rowC[w0o + 1] = s11c + b4.z; rowD[w0o + 1] = s11d + b4.w; }
    }
}
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int C_in, const int H_in, const int W_in,
    const int C_out, const int H_out, const int W_out,
    const int K, const int stride, const int pad)
{
    extern __shared__ float sh_input[];
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    const int tile_w = blockIdx.x % tiles_w;
    const int tile_h = blockIdx.x / tiles_w;
    const int h_out0 = tile_h * TILE_H;
    const int w_out0 = tile_w * TILE_W;
    const int c_out = blockIdx.y * COUT_TILE + threadIdx.z;
    const int n = blockIdx.z;
    const int h_out = h_out0 + threadIdx.y;
    const int w_out = w_out0 + threadIdx.x;
    const int in_h0 = h_out0 * stride - pad;
    const int in_w0 = w_out0 * stride - pad;
    const int in_h = (TILE_H - 1) * stride + K;
    const int in_w = (TILE_W - 1) * stride + K;
    const int plane_elems = in_h * in_w;
    const int tid = threadIdx.x + TILE_W * threadIdx.y + TILE_W * TILE_H * threadIdx.z;
    for (int i = tid; i < C_in * plane_elems; i += BLOCK_THREADS) {
        const int c = i / plane_elems;
        const int r = i - c * plane_elems;
        const int y = r / in_w;
        const int x = r - y * in_w;
        const int h_in = in_h0 + y;
        const int w_in = in_w0 + x;
        float v = 0.0f;
        if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
            v = input[(((long long)n * C_in + c) * H_in + h_in) * W_in + w_in];
        }
        sh_input[i] = v;
    }
    __syncthreads();
    if (h_out >= H_out || w_out >= W_out || c_out >= C_out) return;
    const int y0 = threadIdx.y * stride;
    const int x0 = threadIdx.x * stride;
    float sum = 0.0f;
    for (int c = 0; c < C_in; ++c) {
        const float* sh_plane = sh_input + c * plane_elems;
        const float* w_ch = weight + (((long long)c_out * C_in + c) * K) * K;
        #pragma unroll 4
        for (int kh = 0; kh < K; ++kh) {
            const float* sh_row = sh_plane + (y0 + kh) * in_w;
            const float* w_row = w_ch + kh * K;
            #pragma unroll 4
            for (int kw = 0; kw < K; ++kw) {
                sum += sh_row[x0 + kw] * w_row[kw];
            }
        }
    }
