        }
    }
    const int h0 = h_out0 + ty * 2;
    const int w0o = w_out0 + tx * 2;
    const int cA = c_out0 + cg * 2;
    const int cB = cA + 1;
    const float bA = bias[cA];
    const float bB = bias[cB];
    float* out_base = output + ((long long)n * C_out) * H_out * W_out;
    if (h0 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0) * W_out;
        float* rowB = out_base + ((long long)cB * H_out + h0) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s00a + bA; rowB[w0o] = s00b + bB; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s01a + bA; rowB[w0o + 1] = s01b + bB; }
    }
    if (h0 + 1 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0 + 1) * W_out;
        float* rowB = out_base + ((long long)cB * H_out + h0 + 1) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s10a + bA; rowB[w0o] = s10b + bB; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s11a + bA; rowB[w0o + 1] = s11b + bB; }
